# Surah Ibrahim (chapter 14) — part 4: ayat 31-40 (IDs 1781-1790)
SURAH = 14

ENTRIES = {
1781: (
"کہیے — میرے ایمان والے بندو — نماز قائم کرو اور ہم نے جو تمہیں دیا اس میں سے پوشیدہ اور ظاہر خیرات کرو — اس دن کے آنے سے پہلے جس میں نہ خرید و فروخت ہے نہ دوستی",
"""۱۔ نماز اور صدقہ — قبل اس دن کے جس میں خرید و فروخت کام نہ آئے۔
۲۔ ’’قُل لِّعِبَادِيَ الَّذِينَ آمَنُوا يُقِيمُوا الصَّلَاۃَ وَيُنفِقُوا مِمَّا رَزَقْنَاهُمْ سِرًّا وَعَلَانِيَۃً مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خِلَالٌ‘‘ — کہیے — میرے ایمان والے بندو — نماز قائم کرو اور ہم نے جو تمہیں دیا اس میں سے پوشیدہ اور ظاہر خیرات کرو — اس دن کے آنے سے پہلے جس میں نہ خرید و فروخت ہے نہ دوستی — یعنی کہیے — میرے ایمان والے بندو — نماز قائم کرو اور ہم نے جو تمہیں دیا اس میں سے پوشیدہ اور ظاہر خیرات کرو — اس سے پہلے کہ وہ دن آ جائے جس میں نہ خرید و فروخت ہے نہ دوستی۔
۳۔ عملی سبق: فانی دنیا میں صدقہ اور نماز — آخرت کی خریداری کے واحد ذریعہ ہیں۔"""
),
1782: (
"اللہ وہ ہے جس نے آسمانوں اور زمین کو پیدا کیا — اور آسمان سے پانی برسا — اور اس سے پھل نکالے تمہارے لیے روزی — اور تمہارے لیے کشتیاں زیر حکم ہیں تاکہ سمندر میں اس کے حکم سے چل سکیں — اور تمہارے لیے نہریں زیر حکم ہیں",
"""۱۔ آسمان سے بارش — پھلوں کی روزی — سمندر کی کشتیاں — نہریں — سب اللہ کی تسخیر۔
۲۔ ’’اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقًا لَّكُمْ وَسَخَّرَ لَكُمُ الْفُلْكَ لِتَجْرِيَ فِي الْبَحْرِ بِأَمْرِهِ وَسَخَّرَ لَكُمُ الْأَنْهَارَ‘‘ — اللہ وہ ہے جس نے آسمانوں اور زمین کو پیدا کیا — اور آسمان سے پانی برسا — اور اس سے پھل نکالے تمہارے لیے روزی — اور تمہارے لیے کشتیاں زیر حکم ہیں تاکہ سمندر میں اس کے حکم سے چل سکیں — اور تمہارے لیے نہریں زیر حکم ہیں — یعنی اللہ وہ ہے جس نے آسمانوں اور زمین کو پیدا کیا — اور آسمان سے پانی برسایا — اور اس سے پھل نکالے تمہارے لیے روزی — اور تمہارے لیے کشتیاں زیر حکم کر دیں تاکہ وہ سمندر میں اس کے حکم سے چل سکیں — اور تمہارے لیے نہریں زیر حکم کر دیں۔
۳۔ عملی سبق: ہر نعمت پر شکر — اللہ کا شکر — زندگی کی اساس ہے۔"""
),
1783: (
"اور تمہارے لیے سورج اور چاند کو زیر حکم کیا — ہمیشگی چلنے والے — اور تمہارے لیے رات اور دن کو زیر حکم کیا",
"""۱۔ سورج چاند کا دائمی گردش — رات دن کا بدلاؤ — نظام اللہ کا قائم ہے۔
۲۔ ’’وَسَخَّرَ لَكُمُ الشَّمْسَ وَالْقَمَرَ دَائِبَيْنِ وَسَخَّرَ لَكُمُ اللَّيْلَ وَالنَّهَارَ‘‘ — اور تمہارے لیے سورج اور چاند کو زیر حکم کیا — ہمیشگی چلنے والے — اور تمہارے لیے رات اور دن کو زیر حکم کیا — یعنی تمہارے لیے سورج اور چاند کو زیر حکم کیا — ہمیشگی چلنے والے — اور تمہارے لیے رات اور دن کو زیر حکم کیا۔
۳۔ عملی سبق: وقت کی قدر کریں؛ سورج اور چاند سے سبق لیں؛ دنیا کا نظام اللہ کا مقرر ہے۔"""
),
1784: (
"اور اس نے تمہیں جو کچھ مانگا وہ سب عطا کیا — اور اگر تم اللہ کی نعمتوں کو گننا چاہو تو تم اس کا شمار نہیں کر سکتے — یقیناً انسان بڑا ظالم ناشکرا ہے",
"""۱۔ نعمتوں کا شمار ناممکن؛ انسان ظالم اور ناشکرا ہے — یہ اس کی سرشت ہے۔
۲۔ ’’وَآتَاكُم مِّن كُلِّ مَا سَأَلْتُمُوهُ وَإِن تَعُدُّوا نِعْمَتَ اللَّهِ لَا تُحْصُوهَا إِنَّ الْإِنسَانَ لَظَلُومٌ كَفَّارٌ‘‘ — اور اس نے تمہیں جو کچھ مانگا وہ سب عطا کیا — اور اگر تم اللہ کی نعمتوں کو گننا چاہو تو تم اس کا شمار نہیں کر سکتے — یقیناً انسان بڑا ظالم ناشکرا ہے — یعنی اس نے تمہیں جو کچھ مانگا وہ سب عطا کیا — اور اگر تم اللہ کی نعمتوں کو گننا چاہو تو تم ان کا شمار نہیں کر سکتے — یقیناً انسان بڑا ظالم ناشکرا ہے۔
۳۔ عملی سبق: ہر لمحہ شکر ادا کریں؛ اللہ کی نعمتوں کا شمار کرکے ممکن نہیں — بس اعتراف کریں۔"""
),
1785: (
"اور جب ابراہیم نے دعا کی — اے میرے رب اس شہر کو امن والا بنا — اور مجھے اور میری اولاد کو بتوں کی عبادت سے محفوظ رکھ",
"""۱۔ ابراہیمؑ کی دعا — امن کا حصول اور بتوں سے دوری؛ مکہ مکرمہ کے لیے عظیم دعا۔
۲۔ ’’وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَٰذَا الْبَلَدَ آمِنًا وَاجْنُبْنِي وَبَنِيَّ أَن نَّعْبُدَ الْأَصْنَامَ‘‘ — اور جب ابراہیم نے دعا کی — اے میرے رب اس شہر کو امن والا بنا — اور مجھے اور میری اولاد کو بتوں کی عبادت سے محفوظ رکھ — یعنی یاد کرو جب ابراہیم نے دعا کی — اے میرے رب اس شہر کو امن والا بنا — اور مجھے اور میری اولاد کو بتوں کی عبادت سے محفوظ رکھ۔
۳۔ عملی سبق: اپنے گھر والوں کے باایمان رہنے کی دعا کرتے رہیں؛ اللہ پناہ دینے والا ہے۔"""
),
1786: (
"اے میرے رب — ان بتوں نے بہت سے لوگوں کو گمراہ کیا — پس جو میری پیروی کرے گا وہ مجھ سے ہے — اور جو میری نافرمانی کرے گا تو — تو تو بخشش کرنے والا مہربان ہے",
"""۱۔ بتوں نے لوگوں کو گمراہ کیا؛ پیروکار اہلِ ایمان — نافرمانوں کے لیے اللہ کی مغفرت۔
۲۔ ’’رَّبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِّنَ النَّاسِ فَمَن تَبِعَنِي فَإِنَّهُ مِنِّي وَمَنْ عَصَانِي فَإِنَّكَ غَفُورٌ رَّحِيمٌ‘‘ — اے میرے رب — ان بتوں نے بہت سے لوگوں کو گمراہ کیا — پس جو میری پیروی کرے گا وہ مجھ سے ہے — اور جو میری نافرمانی کرے گا تو — تو تو بخشش کرنے والا مہربان ہے — یعنی اے میرے رب — ان بتوں نے بہت سے لوگوں کو گمراہ کیا — پس جو میری پیروی کرے گا وہ مجھ سے ہے — اور جو میری نافرمانی کرے گا تو تو بخشنے والا مہربان ہے۔
۳۔ عملی سبق: اچھے ساتھیوں کا انتخاب کریں؛ اللہ کی رحمت ہر نافرمان کو توبہ کا موقع دیتی ہے۔"""
),
1787: (
"اے ہمارے رب — میں نے اپنی اولاد کو ایک ایسی وادی میں بسایا جس میں کھیتی نہیں — تیرے محترم گھر کے پاس — اے ہمارے رب — تاکہ وہ نماز قائم کریں — پس تو لوگوں کے دلوں کو ان کی طرف کھینچ دے — اور انہیں پھلوں سے روزی دے — تاکہ وہ شکر کریں",
"""۱۔ مکہ — بے آباد وادی میں اہل بیتؑ کا قیام؛ نماز قائم کرنے کی نیت؛ دلوں کا جھکاؤ اور رزق — ابراہیمؑ کی قبول شدہ دعا۔
۲۔ ’’رَّبَّنَا إِنِّي أَسْكَنتُ مِن ذُرِّيَّتِي بِوَادٍ غَيْرِ ذِي زَرْعٍ عِندَ بَيْتِكَ الْمُحَرَّمِ رَبَّنَا لِيُقِيمُوا الصَّلَاۃَ فَاجْعَلْ أَفْئِدَۃً مِّنَ النَّاسِ تَهْوِي إِلَيْهِمْ وَارْزُقْهُم مِّنَ الثَّمَرَاتِ لَعَلَّهُمْ يَشْكُرُونَ‘‘ — اے ہمارے رب — میں نے اپنی اولاد کو ایک ایسی وادی میں بسایا جس میں کھیتی نہیں — تیرے محترم گھر کے پاس — اے ہمارے رب — تاکہ وہ نماز قائم کریں — پس تو لوگوں کے دلوں کو ان کی طرف کھینچ دے — اور انہیں پھلوں سے روزی دے — تاکہ وہ شکر کریں — یعنی اے ہمارے رب — میں نے اپنی اولاد کو ایک ایسی وادی میں بسایا جس میں کھیتی نہیں — تیرے محترم گھر کے پاس — اے ہمارے رب — تاکہ وہ نماز قائم کریں — پس لوگوں کے دلوں کو ان کی طرف متوجہ فرما دے — اور انہیں پھلوں سے روزی دے — تاکہ وہ شکر اداء کریں۔
۳۔ عملی سبق: رزق اور محبت اللہ کے ہاتھ میں ہیں؛ وہی روزی دیتا ہے اور دلوں کو گردش دیتا ہے۔"""
),
1788: (
"اے ہمارے رب — تو جانتا ہے جو ہم چھپاتے ہیں اور جو ظاہر کرتے ہیں — اور اللہ سے کوئی چیز زمین میں اور آسمان میں پوشیدہ نہیں",
"""۱۔ اللہ کا علم — پوشیدہ اور ظاہر سب کچھ جانتا ہے — اس کے علم سے کوئی چیز پوشیدہ نہیں۔
۲۔ ’’رَّبَّنَا إِنَّكَ تَعْلَمُ مَا نُخْفِي وَمَا نُعْلِنُ وَمَا يَخْفَىٰ عَلَى اللَّهِ مِن شَيْءٍ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ‘‘ — اے ہمارے رب — تو جانتا ہے جو ہم چھپاتے ہیں اور جو ظاہر کرتے ہیں — اور اللہ سے کوئی چیز زمین میں اور آسمان میں پوشیدہ نہیں — یعنی اے ہمارے رب — تو جانتا ہے جو ہم چھپاتے ہیں اور جو ظاہر کرتے ہیں — اور اللہ سے زمین میں اور آسمان میں کوئی چیز پوشیدہ نہیں۔
۳۔ عملی سبق: اکیلے میں بھی اللہ کی نگرانی محسوس کریں؛ ظاہر و باطن میں پاکی رکھیں۔"""
),
1789: (
"سب تعریف اللہ کے لیے ہے جس نے بڑھاپے میں مجھے اسماعیل اور اسحاق دیا — یقیناً میرا رب دعا سننے والا ہے",
"""۱۔ بڑھاپے میں اولاد کا فضل — اللہ کی عطا؛ اسحاقؑ کی پیدائش پر شکر۔
۲۔ ’’الْحَمْدُ لِلَّهِ الَّذِي وَهَبَ لِي عَلَى الْكِبَرِ إِسْمَاعِيلَ وَإِسْحَاقَ إِنَّ رَبِّي لَسَمِيعُ الدُّعَاءِ‘‘ — سب تعریف اللہ کے لیے ہے جس نے بڑھاپے میں مجھے اسماعیل اور اسحاق دیا — یقیناً میرا رب دعا سننے والا ہے — یعنی سب تعریف اللہ کے لیے ہے جس نے بڑھاپے میں مجھے اسماعیل اور اسحاق دیا — یقیناً میرا رب دعا سننے والا ہے۔
۳۔ عملی سبق: اللہ کی عطا پر بڑھاپے میں بھی شکر ادا کریں؛ اس کی دعا قبولیت کی دعا کے ساتھ کرتے رہیں۔"""
),
1790: (
"اے میرے رب مجھے نماز قائم کرنے والا بنا اور میری اولاد میں سے بھی — اے ہمارے رب اور میری دعا قبول فرما",
"""۱۔ نماز کا قیام — نسل کا بھی — دعا کی قبولیت کی التجا۔
۲۔ ’’رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاۃِ وَمِن ذُرِّيَّتِي رَبَّنَا وَتَقَبَّلْ دُعَاءِ‘‘ — اے میرے رب مجھے نماز قائم کرنے والا بنا اور میری اولاد میں سے بھی — اے ہمارے رب اور میری دعا قبول فرما — یعنی اے میرے رب مجھے نماز قائم کرنے والا بنا اور میری اولاد میں سے بھی — اے ہمارے رب اور میری دعا قبول فرما۔
۳۔ عملی سبق: اپنی نسل کی نماز کی دعا کرتے رہیں؛ اللہ ان کی راہ درست فرمائے گا۔"""
),
}
